import {createChatOrchestrator, type OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// Validates specs/hal-engine-config-hooks/spec.md, "Usage reported to afterModelResponse" (re-cinq/HALEngine#93).
// Spec: specs/hal-engine-config-hooks#2

const toolCall: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {}}};

const providerWithRounds = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const usage = async (rounds: MessageChunk[][]): Promise<UsageMetadata | undefined> => {
  let reported: UsageMetadata | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _text, roundUsage) => {
      reported = roundUsage;
    },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}}, async () => ({
    result: 'found',
  }));
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'ask', timestamp: '2026-01-01T00:00:00.000Z'}],
  };

  await createChatOrchestrator(providerWithRounds(rounds), new PromptBuilder({identity: 'test'}), registry, {
    hooks,
  }).processMessage(session);

  return reported;
};

it('adds usage from each provider call in a tool turn', async () => {
  expect(
    await usage([
      [toolCall, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 1, totalTokens: 11}}],
      [
        {type: 'text', text: 'done'},
        {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 2, totalTokens: 22}},
      ],
    ])
  ).toEqual({inputTokens: 30, outputTokens: 3, totalTokens: 33});
});

